<script setup lang="ts">
import {ElButton, ElInput, ElInputNumber, ElCheckbox} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {api,ApiError,type Account} from '../../api'
import {confirmAction} from '../../shared/confirm'
import {base,blankRestaurant,reasonText,type Restaurant} from './types'
import TablesPanel from './TablesPanel.vue'
import StaffPanel from './StaffPanel.vue'
import './dining.css'
const props=defineProps<{account:Account;recordId?:string;embedded?:boolean}>(),route=useRoute(),router=useRouter()
const targetId=computed(()=>props.recordId??String(route.params.restaurantId))
const emit=defineEmits<{saved:[];close:[]}>()
const canManage=computed(()=>props.account.permissionCodes.includes('dining.manage')),isNew=computed(()=>targetId.value==='new')
const tablesPanel=ref<{canClose:()=>Promise<boolean>}|null>(null),staffPanel=ref<{canClose:()=>Promise<boolean>}|null>(null)
const form=ref(blankRestaurant()),snapshot=ref(''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),conflict=ref(false)
interface Creation {requestKey:string;body:Omit<Restaurant,'id'|'revision'|'fulfillmentStore'|'tableCount'>}
const pending=ref<Creation|null>(null)
const storageKey=()=>`mall.dining.creation.${props.account.accountId}`
function restoreCreation(){pending.value=null;const raw=sessionStorage.getItem(storageKey());if(raw){const stored=JSON.parse(raw) as Creation;if(typeof stored.requestKey!=='string'||!stored.body||typeof stored.body.name!=='string')throw new Error('待恢复的创建请求格式无效，请检查浏览器存储。');pending.value=stored;form.value={...blankRestaurant(),...stored.body};notice.value='上次创建结果尚未确认。资料已锁定，保存将使用原请求恢复，避免重复建店。'}}
const locked=computed(()=>!!pending.value)
const dirty=computed(()=>!!snapshot.value&&JSON.stringify(form.value)!==snapshot.value)
let generation=0
async function load(){const current=++generation;loading.value=true;error.value='';snapshot.value='';form.value=blankRestaurant();try{const result=isNew.value?blankRestaurant():await api<Restaurant>(`${base}/restaurants/${encodeURIComponent(String(targetId.value))}`);if(current===generation){form.value={...result};snapshot.value=JSON.stringify(result);conflict.value=false;if(isNew.value)restoreCreation()}}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
async function reload(){if(!dirty.value||await confirmAction('重新读取将丢弃当前未保存的餐饮店资料，确定继续吗？'))load()}
async function save(){if(!canManage.value||busy.value||conflict.value)return;const data=form.value;if(!data.name.trim()||!data.address.trim()||!data.contactName.trim()||!data.contactPhone.trim()||data.latitude===null||data.longitude===null||!Number.isFinite(data.latitude)||!Number.isFinite(data.longitude)||Math.abs(data.latitude)>90||Math.abs(data.longitude)>180){error.value='请填写店名、地址、联系人、联系电话及有效经纬度。';return}const current=generation;busy.value=true;error.value='';notice.value='';try{const {id,fulfillmentStore,tableCount,revision,...fields}=data;if(isNew.value&&!pending.value){const creation:Creation={requestKey:crypto.randomUUID(),body:{...fields}};sessionStorage.setItem(storageKey(),JSON.stringify(creation));pending.value=creation}
const result=await api<Restaurant>(isNew.value?`${base}/restaurants`:`${base}/restaurants/${id}`,{method:isNew.value?'POST':'PATCH',body:JSON.stringify(isNew.value?{...pending.value!.body,requestKey:pending.value!.requestKey}:{...fields,revision})});if(current!==generation)return;if(isNew.value){sessionStorage.removeItem(storageKey());pending.value=null}form.value={...result};snapshot.value=JSON.stringify(result);notice.value='餐饮店资料已保存，履约前置仓由系统自动匹配。';if(props.embedded){emit('saved');return}if(isNew.value)await router.replace(`/dining-alliance/restaurants/${result.id}`)}catch(e){if(current===generation){if(isNew.value&&e instanceof ApiError&&[400,422].includes(e.status)){sessionStorage.removeItem(storageKey());pending.value=null}conflict.value=!isNew.value&&e instanceof ApiError&&e.status===409;error.value=`${reasonText(e)}${conflict.value?'；已保留编辑草稿，请复制需保留内容后重新读取最新资料。':''}`}}finally{if(current===generation)busy.value=false}}
async function canClose(){if(busy.value)return false;if(dirty.value&&!await confirmAction('餐饮店资料尚未保存，确定关闭吗？'))return false;if(tablesPanel.value&&!await tablesPanel.value.canClose())return false;if(staffPanel.value&&!await staffPanel.value.canClose())return false;return true}
defineExpose({canClose})
onBeforeRouteLeave(canClose)
watch(()=>[targetId.value,props.account.accountId],()=>{busy.value=false;load()},{immediate:true})
</script>
<template><section class="page-content dining-page"><header class="page-heading"><div><h1>{{isNew?'新增餐饮店':form.name||'餐饮店详情'}}</h1><p>餐饮店提供消费场景，不参与库存和履约，不出现在定位找店列表。</p></div><el-button v-if="embedded" @click="async()=>{if(await canClose())emit('close')}">关闭</el-button><RouterLink v-else to="/dining-alliance"><el-button>返回列表</el-button></RouterLink></header><p v-if="loading" role="status">正在读取餐饮店…</p><p v-if="error" role="alert" class="error">{{error}} <el-button :disabled="busy" @click="reload">重新读取</el-button></p><p v-if="notice" role="status" class="notice">{{notice}}</p><template v-if="!loading&&snapshot"><form class="panel" @submit.prevent="save"><h2>餐饮店资料</h2><div class="fields"><label>餐饮店名称<el-input v-model="form.name" aria-label="餐饮店名称" maxlength="100" :disabled="!canManage||busy||locked"/></label><label>联系人<el-input v-model="form.contactName" aria-label="联系人" maxlength="100" :disabled="!canManage||busy||locked"/></label><label>联系电话<el-input v-model="form.contactPhone" aria-label="联系电话" maxlength="30" :disabled="!canManage||busy||locked"/></label><label>店铺地址<el-input v-model="form.address" aria-label="店铺地址" maxlength="500" :disabled="!canManage||busy||locked"/></label><label>纬度<el-input-number v-model="form.latitude" aria-label="纬度" :min="-90" :max="90" :precision="6" :step="0.000001" :disabled="!canManage||busy||locked"/></label><label>经度<el-input-number v-model="form.longitude" aria-label="经度" :min="-180" :max="180" :precision="6" :step="0.000001" :disabled="!canManage||busy||locked"/></label><p class="wide">履约前置仓：{{form.fulfillmentStore?.name||'保存后按餐饮店位置自动匹配'}}。缺货时不切换其他仓。</p><el-checkbox v-model="form.enabled" :disabled="!canManage||busy||locked">启用餐饮店</el-checkbox></div><div class="toolbar" v-if="canManage"><el-button native-type="submit" type="primary" :loading="busy" :disabled="conflict">保存餐饮店</el-button><span v-if="dirty">有未保存修改</span></div></form><template v-if="!isNew"><TablesPanel ref="tablesPanel" :key="`tables:${form.id}:${account.accountId}`" :restaurant-id="form.id" :can-manage="canManage"/><StaffPanel ref="staffPanel" v-if="canManage" :key="`staff:${form.id}:${account.accountId}`" :restaurant-id="form.id" :can-manage="canManage"/></template></template></section></template>
